/**
 * Offline support.
 *
 * Hand-written rather than generated by a PWA plugin. It is ~70 lines, it adds no
 * dependency, and — more importantly — it makes the caching policy explicit, which
 * matters because the wrong policy here costs learners real mobile data.
 *
 * Policy:
 *   - Only same-origin GETs are touched. YouTube and i.ytimg.com are never cached
 *     or intercepted; video stays entirely under the browser's own control.
 *   - Navigations are network-first so a learner always gets fresh lesson content
 *     when online, falling back to cache and then to the offline page.
 *   - Static assets are stale-while-revalidate: instant from cache, refreshed in
 *     the background.
 *
 * Caching is runtime-only: a lesson becomes available offline once it has been
 * visited. Precaching all six lessons up front would spend data the learner never
 * agreed to spend.
 */

const CACHE = 'negocio-digital-v1';
const OFFLINE_URL = '/offline';

// Kept minimal on purpose — only the shell needed to render the offline fallback.
const PRECACHE = ['/', OFFLINE_URL];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Cache individually: one unreachable URL must not fail the whole install.
      await Promise.all(
        PRECACHE.map((url) =>
          cache.add(new Request(url, { cache: 'reload' })).catch(() => undefined)
        )
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key)));
      await self.clients.claim();
    })()
  );
});

/**
 * Cache a page on request from the page itself.
 *
 * The very first visit installs the worker but is not intercepted by it, so that
 * page would have no offline copy until it was visited a second time. For an
 * audience on unreliable mobile data that is exactly the wrong failure: you read
 * a lesson, lose signal, reload, and it is gone. The page therefore asks to be
 * cached once the worker is active.
 */
self.addEventListener('message', (event) => {
  const data = event.data;
  if (!data || data.type !== 'cache-page' || typeof data.url !== 'string') return;

  event.waitUntil(
    (async () => {
      try {
        if (new URL(data.url).origin !== self.location.origin) return;
        const cache = await caches.open(CACHE);
        await cache.add(new Request(data.url, { cache: 'reload' }));
      } catch {
        /* best effort — offline support is a bonus, never a requirement */
      }
    })()
  );
});

async function networkFirst(request) {
  const cache = await caches.open(CACHE);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch {
    const cached = await cache.match(request);
    if (cached) return cached;
    const offline = await cache.match(OFFLINE_URL);
    if (offline) return offline;
    return new Response('Sem conexão.', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request);

  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);

  return cached ?? (await network) ?? Response.error();
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  if (request.method !== 'GET') return;

  // Never intercept another origin. Video, thumbnails and anything third-party
  // bypass the worker entirely.
  if (new URL(request.url).origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request));
    return;
  }

  event.respondWith(staleWhileRevalidate(request));
});
